"""Draft: observed Sprout employee/attendance sync; no absence or leave fabrication."""
import datetime
import math
import time
import uuid
from zoneinfo import ZoneInfo


def run_sync(api):
    started = datetime.datetime.now(datetime.timezone.utc).isoformat()
    run_key = str(uuid.uuid4())
    deadline = time.monotonic() + 60
    call_count = 0

    def call(method, **kwargs):
        nonlocal call_count
        terminal_run_log = kwargs.get("type_slug") == "hj_sync_runs" and kwargs.get("record", {}).get("data", {}).get("status") in ("failed", "partial", "succeeded")
        if call_count >= (200 if terminal_run_log else 199) or time.monotonic() >= deadline:
            raise RuntimeError("Sync bounded run exceeded 200 bridge calls or 60 seconds; reduce the selected population. A completed full sync was not recorded.")
        call_count += 1
        return method(**kwargs)

    settings = call(api.extension.settings)
    if settings.get("sync_enabled") is not True or settings.get("source_mapping_reviewed") is not True:
        raise ValueError("Sprout sync is disabled: complete the reviewed source/identity mapping and explicitly enable sync in extension setup before running. No connector calls or Records writes were made.")
    def integer(key, minimum, maximum, default=None):
        value = settings.get(key, default)
        if isinstance(value, bool) or not isinstance(value, (int, float)) or int(value) != value or not minimum <= value <= maximum:
            raise ValueError("Setup " + key + " must be an integer in " + str(minimum) + ".." + str(maximum))
        return int(value)

    company_id = integer("company_id", 1, 2147483647)
    page_limit = integer("sync_page_limit", 1, 10, 10)
    rows_per_page = integer("sync_rows_per_page", 1, 100, 100)
    max_portals = integer("max_portals", 1, 50, 50)
    lookback = integer("sync_lookback_days", 1, 35, 35)
    in_mode = integer("attendance_log_type_in", 0, 2147483647)
    grace = integer("late_grace_minutes", 0, 120, 15)
    zone_name = settings.get("timezone", "Asia/Manila")
    if not isinstance(zone_name, str) or "/" not in zone_name:
        raise ValueError("timezone must be an explicit IANA area/location, such as Asia/Manila")
    try:
        zone = ZoneInfo(zone_name)
    except Exception as error:
        raise ValueError("Timezone " + zone_name + " is unavailable. Install/verify IANA tzdata in the Pyodide runtime before enabling sync; no connector calls or Records writes were made.") from error
    today = datetime.datetime.now(zone).date()
    from_date = today - datetime.timedelta(days=lookback - 1)
    start_parts = str(settings.get("work_start_time", "09:00")).split(":")
    if len(start_parts) != 2:
        raise ValueError("work_start_time must be HH:mm")
    start_time = datetime.time(int(start_parts[0]), int(start_parts[1]))
    if settings.get("work_week", "mon_fri") not in ("mon_fri", "mon_sat"):
        raise ValueError("work_week must be mon_fri or mon_sat")
    month_start = today.replace(day=1)
    completed_month_end = month_start - datetime.timedelta(days=1)
    completed_month_start = completed_month_end.replace(day=1)
    pto_text = settings.get("pto_leave_type_ids", "")
    if not isinstance(pto_text, str) or not pto_text.strip():
        raise ValueError("pto_leave_type_ids must contain reviewed positive Sprout leave type IDs")
    pto_ids = [int(value.strip()) for value in pto_text.split(",")]
    if not 1 <= len(pto_ids) <= 10 or any(value <= 0 for value in pto_ids) or len(set(pto_ids)) != len(pto_ids):
        raise ValueError("pto_leave_type_ids must contain 1..10 distinct positive IDs")
    approved_status = integer("leave_approved_status_id", 1, 2147483647)
    office_text = settings.get("work_location_office_codes", "")
    if not isinstance(office_text, str) or not office_text.strip():
        raise ValueError("work_location_office_codes requires reviewed exact source codes")
    office_codes = {value.strip() for value in office_text.split(",") if value.strip()}
    holidays = {datetime.date.fromisoformat(value.strip()) for value in str(settings.get("work_holidays", "")).split(",") if value.strip()}
    calendar_reviewed = settings.get("company_uniform_schedule_reviewed") is True

    def paged_tool(server, tool, filters):
        rows = []
        for page in range(1, page_limit + 1):
            result = call(api.connectors.invoke, server=server, tool=tool,
                          args=dict(filters, PageNumber=page, RowsPerPage=rows_per_page))
            if not isinstance(result, dict) or not isinstance(result.get("data"), list) or not isinstance(result.get("pagination"), dict):
                raise ValueError(server + "/" + tool + " returned an unknown shape; expected captured {data, pagination}. No guessed normalization is allowed.")
            meta = result["pagination"]
            current, total = meta.get("currentPage"), meta.get("totalPages")
            if isinstance(current, bool) or isinstance(total, bool) or not isinstance(current, int) or not isinstance(total, int) or current != page or total < 0:
                raise ValueError(tool + " pagination must contain exact integer currentPage/totalPages")
            if len(result["data"]) > rows_per_page or any(not isinstance(row, dict) for row in result["data"]):
                raise ValueError(tool + " page exceeded its bound or contained invalid rows")
            rows.extend(result["data"])
            if total <= page:
                return rows
        raise ValueError(tool + " has more than sync_page_limit pages; increase the reviewed bounded configuration. No partial population will be projected.")

    def record_rows(slug):
        rows, cursor = [], None
        for _ in range(10):
            args = {"type_slug": slug, "limit": 200}
            if cursor is not None:
                args["cursor"] = cursor
            page = call(api.records.list, **args)
            if not isinstance(page, dict) or not isinstance(page.get("records"), list):
                raise ValueError("Records list returned an invalid page for " + slug)
            rows.extend(page["records"])
            next_cursor = page.get("nextCursor")
            if next_cursor is None:
                return rows
            if not isinstance(next_cursor, str) or next_cursor == cursor:
                raise ValueError("Records cursor is invalid or repeated for " + slug)
            cursor = next_cursor
        raise ValueError("Employee mapping exceeds 2000 rows; narrow the reviewed sync scope")

    def upsert(slug, key, data, portal_id=None):
        args = {"type_slug": slug, "key": {"field": "sync_key", "value": key},
                "record": {"title": data["employee_name"] if "employee_name" in data else data["run_label"],
                           "data": dict(data, sync_key=key)}}
        if portal_id is not None:
            args["portal_id"] = portal_id
        return call(api.records.upsert, **args)

    run_data = {"run_label": "Sprout sync " + started, "status": "running", "started_at": started,
                "employee_count": 0, "portal_count": 0}
    upsert("hj_sync_runs", run_key, run_data)
    try:
        employees = paged_tool("sprout-employee", "list_employees", {"CompanyId": company_id, "Include": ["WorkInformation"]})
        if len(employees) > 100:
            raise ValueError("Draft run supports at most 100 source employees; implement resumable batches before widening it")
        source_by_id = {}
        for item in employees:
            basic = item.get("basicInformation")
            if not isinstance(basic, dict):
                raise ValueError("list_employees requires captured basicInformation rows")
            system_id = basic.get("systemId")
            employee_number, first, last = basic.get("employeeId"), basic.get("firstName"), basic.get("lastName")
            if isinstance(system_id, bool) or not isinstance(system_id, int) or system_id <= 0 or not isinstance(employee_number, str) or not isinstance(first, str) or not isinstance(last, str):
                raise ValueError("Employee basicInformation requires numeric systemId and exact employeeId/firstName/lastName strings")
            name = (first + " " + last).strip()
            if not name or system_id in source_by_id:
                raise ValueError("Employee source has an empty name or duplicate systemId")
            source_by_id[system_id] = {"employee_name": name, "sprout_system_id": system_id,
                                       "employee_number": employee_number, "company_id": company_id, "synced_at": started}
            work = item.get("workInformation")
            if isinstance(work, dict):
                if isinstance(work.get("employmentStatusLabel"), str):
                    source_by_id[system_id]["employment_status"] = work["employmentStatusLabel"]
                if isinstance(work.get("hireDate"), str):
                    source_by_id[system_id]["start_date"] = datetime.date.fromisoformat(work["hireDate"][:10]).isoformat()

        mappings = {}
        for record in record_rows("hj_employee_map"):
            data = record.get("data", {})
            system_id, user_id = data.get("sprout_system_id"), data.get("workspace_user_id")
            if system_id in source_by_id and user_id:
                if data.get("sync_key") != "sprout:" + str(system_id):
                    raise ValueError("Reviewed employee mapping sync_key must be sprout:<systemId>; repair the mapping before enabling sync to avoid duplicate records")
                if system_id in mappings:
                    raise ValueError("Duplicate reviewed workspace mapping for a Sprout systemId")
                mappings[system_id] = user_id
        missing = [str(key) for key in source_by_id if key not in mappings]
        if missing:
            raise ValueError("Populate hj_employee_map.workspace_user_id using reviewed exact email + Sprout systemId mappings before syncing. Missing system IDs: " + ",".join(missing[:20]))
        users = call(api.users.list)
        if not isinstance(users, list) or len(users) > 2000:
            raise ValueError("Workspace user inventory is invalid or exceeds the 2000-user bound")
        user_ids = {user["id"] for user in users if isinstance(user, dict) and isinstance(user.get("id"), str) and user.get("is_external") is False}
        if any(user_id not in user_ids for user_id in mappings.values()):
            raise ValueError("Reviewed employee mapping references an unavailable Workspace user")
        portals = call(api.portals.list)
        if not isinstance(portals, list) or len(portals) > max_portals:
            raise ValueError("Portal inventory is invalid or exceeds configured max_portals=" + str(max_portals) + "; no partial portal population will be projected")
        destinations = {}
        for portal in portals:
            if not isinstance(portal, dict) or not portal.get("clientId") or not portal.get("portalId"):
                raise ValueError("Portal inventory requires exact clientId and portalId")
            assigned = call(api.employees.list, client_id=portal["clientId"])
            if not isinstance(assigned, list) or len(assigned) > 200:
                raise ValueError("Client staffing is invalid or exceeds 200 employees")
            assigned_ids = {row["user_id"] for row in assigned if isinstance(row, dict) and row.get("client_id") == portal["clientId"] and isinstance(row.get("user_id"), str)}
            for system_id, user_id in mappings.items():
                if user_id in assigned_ids:
                    destinations.setdefault(system_id, []).append(portal["portalId"])

        logs = paged_tool("sprout-time-attendance", "list_attendance_logs", {
            "CompanyId": company_id, "DateFrom": from_date.isoformat(), "DateTo": today.isoformat()})
        first_in, first_location = {}, {}
        for log in logs:
            if not all(key in log for key in ("logID", "id", "inOutMode", "logTime")):
                raise ValueError("Attendance source must match captured logID/id/inOutMode/logTime fields")
            if log["inOutMode"] != in_mode:
                continue
            if not isinstance(log["id"], int) or log["id"] not in source_by_id:
                raise ValueError("Attendance employee id is absent from the complete selected company population")
            stamp = datetime.datetime.fromisoformat(str(log["logTime"]).replace("Z", "+00:00"))
            if stamp.tzinfo is None:
                stamp = stamp.replace(tzinfo=zone)
            stamp = stamp.astimezone(zone)
            if not from_date <= stamp.date() <= today:
                raise ValueError("Attendance timestamp lies outside requested source window")
            key = (log["id"], stamp.date().isoformat())
            if key not in first_in or stamp < first_in[key]:
                first_in[key] = stamp
                location = log.get("workLocationInfo")
                code = location.get("workLocationCode") if isinstance(location, dict) else None
                first_location[key] = "office" if isinstance(code, str) and code in office_codes else None

        warnings, leave_rows, leave_balances, approved_days = [], [], {}, {}
        def number(value, label):
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
                raise ValueError(label + " must be a finite number from the official response")
            return value
        def source_day(value):
            if not isinstance(value, str):
                raise ValueError("Leave source date must be an ISO date/dateTime string")
            return datetime.date.fromisoformat(value[:10])
        try:
            leave_names = {}
            for system_id in source_by_id:
                raw_types = call(api.connectors.invoke, server="sprout-employee", tool="get_employee_leave_types", args={"id": str(system_id)})
                types = raw_types if isinstance(raw_types, list) else [raw_types]
                available = {}
                for leave_type in types:
                    if not isinstance(leave_type, dict) or isinstance(leave_type.get("leaveTypeId"), bool) or not isinstance(leave_type.get("leaveTypeId"), int) or not isinstance(leave_type.get("leaveTypeName"), str):
                        raise ValueError("Employee leave types must match official leaveTypeId/leaveTypeName fields")
                    available[leave_type["leaveTypeId"]] = leave_type["leaveTypeName"]
                if any(type_id not in available for type_id in pto_ids):
                    raise ValueError("Configured PTO leave type is unavailable for employee " + str(system_id))
                leave_names[system_id] = {available[type_id] for type_id in pto_ids}
                ending = 0
                for type_id in pto_ids:
                    credits = call(api.connectors.invoke, server="sprout-time-attendance", tool="get_leave_credits", args={
                        "EmployeeId": system_id, "LeaveTypeId": type_id, "DateFrom": month_start.isoformat(), "DateTo": today.isoformat()})
                    if not isinstance(credits, dict) or credits.get("leaveTypeId") != type_id:
                        raise ValueError("Leave credit response does not match requested leaveTypeId")
                    number(credits.get("available"), "available")
                    ending += number(credits.get("current"), "current")
                leave_balances[system_id] = {"pto_balance_ending": ending, "pto_used_month": 0}
            requests, seen = [], set()
            if source_by_id:
                for page in range(1, page_limit + 1):
                    search = call(api.connectors.invoke, server="sprout-time-attendance", tool="create_leave_search", args={
                        "companyIds": [company_id], "employeeIds": list(source_by_id), "dateFrom": from_date.isoformat(),
                        "dateTo": today.isoformat(), "pageNumber": page, "rowsPerPage": rows_per_page})
                    search_id = search if isinstance(search, str) else search.get("SearchCriteriaId") if isinstance(search, dict) and set(search) == {"SearchCriteriaId"} else None
                    if not isinstance(search_id, str) or not search_id.strip():
                        raise ValueError("Leave search creation must return exact string or {SearchCriteriaId:string}")
                    result = call(api.connectors.invoke, server="sprout-time-attendance", tool="get_leave_search", args={"SearchCriteriaId": search_id})
                    if not isinstance(result, dict) or not isinstance(result.get("data"), list) or isinstance(result.get("currentPage"), bool) or result.get("currentPage") != page or isinstance(result.get("totalPages"), bool) or not isinstance(result.get("totalPages"), int) or result["totalPages"] < 0:
                        raise ValueError("Leave search must match the official flat data/currentPage/totalPages response")
                    if len(result["data"]) > rows_per_page:
                        raise ValueError("Leave search exceeded its page bound")
                    for row in result["data"]:
                        if not isinstance(row, dict) or isinstance(row.get("id"), bool) or not isinstance(row.get("id"), int) or row["id"] in seen or row.get("employeeId") not in source_by_id:
                            raise ValueError("Leave search has unknown employee, invalid ID, or duplicate paging rows")
                        seen.add(row["id"]); requests.append(row)
                    if result["totalPages"] <= page:
                        break
                else:
                    raise ValueError("Leave search exceeds sync_page_limit; no partial PTO total is projected")
            for row in requests:
                system_id = row["employeeId"]
                if not isinstance(row.get("leaveTypeName"), str) or isinstance(row.get("statusId"), bool) or not isinstance(row.get("statusId"), int):
                    raise ValueError("Leave request requires official leaveTypeName/statusId fields")
                begin, end = source_day(row.get("dateFrom")), source_day(row.get("dateTo"))
                if begin > end:
                    raise ValueError("Leave request date range is reversed")
                leave_rows.append((system_id, row["id"], {"leave_type": row["leaveTypeName"], "start_date": begin.isoformat(), "end_date": end.isoformat(), "status": "approved" if row["statusId"] == approved_status else str(row["statusId"])}))
                if row["statusId"] != approved_status:
                    continue
                detail = call(api.connectors.invoke, server="sprout-time-attendance", tool="get_leave_request", args={"id": str(row["id"])})
                if not isinstance(detail, dict) or detail.get("employeeId") != system_id or detail.get("requestStatusId") != approved_status or detail.get("leaveTypeName") != row["leaveTypeName"] or not isinstance(detail.get("details"), list):
                    raise ValueError("Approved leave detail must match employee/status/type and contain dated details")
                for entry in detail["details"]:
                    if not isinstance(entry, dict) or type(entry.get("isWhole")) is not bool or type(entry.get("paid")) is not bool:
                        raise ValueError("Leave detail requires exact isWhole/paid booleans")
                    day = source_day(entry.get("date"))
                    if not begin <= day <= end:
                        raise ValueError("Leave detail falls outside its source request dates")
                    amount = 1 if entry["isWhole"] else 0.5
                    key = (system_id, day)
                    approved_days[key] = approved_days.get(key, 0) + amount
                    if approved_days[key] > 1:
                        raise ValueError("Approved leave detail overlaps more than one whole day; review duplicate requests")
                    if month_start <= day <= today and entry["paid"] and row["leaveTypeName"] in leave_names[system_id]:
                        leave_balances[system_id]["pto_used_month"] += amount
        except Exception as leave_error:
            # Neither incomplete balance nor incomplete usage is published as zero.
            leave_rows, leave_balances, approved_days = [], {}, {}
            warnings.append("Leave/PTO projection blocked: " + str(leave_error))

        monthly = {}
        if calendar_reviewed and not warnings:
            periods = [(month_start, today - datetime.timedelta(days=1)), (completed_month_start, completed_month_end)]
            for period_start, period_end in periods:
                if period_end < period_start or from_date > period_start:
                    warnings.append("Monthly period skipped: source does not cover " + period_start.strftime("%Y-%m") + " through its last completed local day")
                    continue
                work_days = []
                day = period_start
                while day <= period_end:
                    if day.weekday() < (5 if settings.get("work_week", "mon_fri") == "mon_fri" else 6) and day not in holidays:
                        work_days.append(day)
                    day += datetime.timedelta(days=1)
                for system_id, employee in source_by_id.items():
                    if "start_date" not in employee:
                        warnings.append("Monthly attendance blocked for " + str(system_id) + ": official hireDate missing")
                        continue
                    eligible = [day for day in work_days if day >= datetime.date.fromisoformat(employee["start_date"]) and approved_days.get((system_id, day), 0) != 1]
                    if any(approved_days.get((system_id, day), 0) == 0.5 for day in eligible):
                        warnings.append("Monthly attendance blocked for " + str(system_id) + ": half-day leave requires an approved attendance denominator rule")
                        continue
                    observed = [(day, first_in[(system_id, day.isoformat())]) for day in eligible if (system_id, day.isoformat()) in first_in]
                    late = sum(stamp > datetime.datetime.combine(day, start_time, zone) + datetime.timedelta(minutes=grace) for day, stamp in observed)
                    if not eligible:
                        warnings.append("Monthly attendance has no eligible working days for " + str(system_id))
                        continue
                    data = {"month": period_start.strftime("%Y-%m"), "calculation_end_date": period_end.isoformat(), "days_present": len(observed) - late,
                            "days_late": late, "days_absent": len(eligible) - len(observed), "working_days": len(eligible),
                            "attendance_rate": round(len(observed) / len(eligible) * 100, 2)}
                    if all(first_location[(system_id, day.isoformat())] is not None for day, _ in observed):
                        data["office_days"] = len(observed)
                    else:
                        warnings.append("Office-day total unavailable for " + str(system_id) + ": unknown source location code")
                    monthly[(system_id, data["month"])] = data
        elif not calendar_reviewed:
            warnings.append("Monthly attendance blocked: company_uniform_schedule_reviewed must be true")

        for system_id, employee in source_by_id.items():
            record = upsert("hj_employee_map", "sprout:" + str(system_id), dict(employee, workspace_user_id=mappings[system_id]))
            if not isinstance(record, dict) or not isinstance(record.get("title"), str):
                raise ValueError("Employee Records upsert did not return a canonical title")
            for portal_id in destinations.get(system_id, []):
                call(api.snapshots.upsert, portal_id=portal_id, source="sprout", entity_type="employee",
                     rows=[{"external_id": str(system_id), "payload": {"employee_name": record["title"]}}], replace=False)
        projected = 0
        for (system_id, day), stamp in sorted(first_in.items()):
            employee = source_by_id[system_id]
            threshold = datetime.datetime.combine(stamp.date(), start_time, zone) + datetime.timedelta(minutes=grace)
            status = "late" if stamp > threshold else "present"
            for portal_id in destinations.get(system_id, []):
                data = dict(employee, attendance_date=day, clock_in_time=stamp.strftime("%H:%M"), status=status)
                data.pop("company_id")
                if first_location[(system_id, day)] is not None:
                    data["work_location"] = first_location[(system_id, day)]
                mtd = monthly.get((system_id, month_start.strftime("%Y-%m")))
                if day == today.isoformat() and mtd is not None:
                    data["attendance_rate_mtd"] = mtd["attendance_rate"]
                record = upsert("hj_attendance_daily", "sprout:" + str(system_id) + ":" + day, data, portal_id)
                if not isinstance(record, dict) or not isinstance(record.get("data"), dict):
                    raise ValueError("Records upsert did not return its canonical record/data shape")
                if day == today.isoformat():
                    canonical = record["data"]
                    payload = {"employee_name": record["title"], "clock_in_time": canonical["clock_in_time"],
                               "status": canonical["status"], "work_location": canonical.get("work_location")}
                    for optional in ("attendance_rate_mtd", "employment_status", "start_date"):
                        if optional in canonical:
                            payload[optional] = canonical[optional]
                    call(api.snapshots.upsert, portal_id=portal_id, source="sprout", entity_type="attendance",
                         rows=[{"external_id": str(system_id), "payload": payload, "observed_at": stamp.isoformat()}], replace=False)
                    projected += 1
        for system_id, employee in source_by_id.items():
            for portal_id in destinations.get(system_id, []):
                base = {"employee_name": employee["employee_name"], "sprout_system_id": system_id, "synced_at": started}
                if system_id in leave_balances:
                    record = upsert("hj_leave_balances", "sprout:" + str(system_id) + ":" + month_start.strftime("%Y-%m"), dict(base, month=month_start.strftime("%Y-%m"), **leave_balances[system_id]), portal_id)
                    d = record["data"]
                    call(api.snapshots.upsert, portal_id=portal_id, source="sprout", entity_type="leave_balance", rows=[{"external_id": str(system_id), "payload": {"employee_name": record["title"], "month": d["month"], "pto_balance_ending": d["pto_balance_ending"], "pto_used_month": d["pto_used_month"]}}], replace=False)
                for (employee_id, month), metric in monthly.items():
                    if employee_id != system_id:
                        continue
                    record = upsert("hj_attendance_month", "sprout:" + str(system_id) + ":" + month, dict(base, **metric), portal_id)
                    payload = dict(record["data"]); payload.pop("sync_key", None); payload["employee_name"] = record["title"]
                    call(api.snapshots.upsert, portal_id=portal_id, source="sprout", entity_type="attendance_month", rows=[{"external_id": str(system_id) + ":" + payload["month"], "payload": payload, "observed_at": started}], replace=False)
        for system_id, request_id, request in leave_rows:
            for portal_id in destinations.get(system_id, []):
                data = dict(request, employee_name=source_by_id[system_id]["employee_name"], sprout_system_id=system_id, synced_at=started)
                record = upsert("hj_leave_requests", "sprout:leave:" + str(request_id), data, portal_id)
                d = record["data"]
                call(api.snapshots.upsert, portal_id=portal_id, source="sprout", entity_type="leave_request", rows=[{"external_id": str(request_id), "payload": {"employee_name": record["title"], "type": d["leave_type"], "start_date": d["start_date"], "end_date": d["end_date"], "status": d["status"]}, "observed_at": started}], replace=False)
        blockers = "; ".join(warnings) or ""
        final_status = "partial" if warnings else "succeeded"
        run_data.update(status=final_status, finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                        error_text=blockers, employee_count=len(source_by_id), portal_count=len({p for ps in destinations.values() for p in ps}))
        upsert("hj_sync_runs", run_key, run_data)
        return {"status": final_status, "employees": len(source_by_id), "current_attendance_snapshots": projected, "blockers": blockers}
    except Exception as error:
        run_data.update(status="failed", finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(), error_text=str(error)[:4000])
        # The failure remains primary if the bounded budget prevents logging it.
        if call_count < 200 and time.monotonic() < deadline:
            try:
                upsert("hj_sync_runs", run_key, run_data)
            except Exception as logging_error:
                raise RuntimeError("Sync failed: " + str(error) + "; failure logging also failed: " + str(logging_error)) from error
        raise


result = run_sync(api)
